UPDATE user_learned_business_words
SET review_count = review_count + 1
WHERE user_id = #{userId} AND word_id = #{wordId}

UPDATE user_learned_abroad_words
SET review_count = review_count + 1
WHERE user_id = #{userId} AND word_id = #{wordId}

UPDATE user_learned_words
SET review_count = review_count + 1
WHERE user_id = #{userId} AND word_id = #{wordId} AND type = #{type}

