SELECT w.*
FROM words w
LEFT JOIN user_learned_words ulw ON w.id = ulw.word_id AND ulw.user_id = #{userId}
WHERE w.type <= #{userType}
AND ulw.word_id IS NULL
ORDER BY w.id
LIMIT #{num}

SELECT w.*
FROM business_words w
LEFT JOIN user_learned_business_words ulbw ON w.id = ulbw.word_id AND ulbw.user_id = #{userId}
WHERE w.type = #{userType}
AND ulbw.word_id IS NULL
ORDER BY w.id
LIMIT #{num}

SELECT w.*
FROM abroad_words w
LEFT JOIN user_learned_abroad_words ulbw ON w.id = ulbw.word_id AND ulbw.user_id = #{userId}
WHERE w.type = #{userType}
AND ulbw.word_id IS NULL
ORDER BY w.id
LIMIT #{num}

SELECT word_count
FROM user_daily_word_count
WHERE study_date = #{now} AND user_id = #{userId}

SELECT review_count
FROM user_daily_word_count
WHERE study_date = #{now} AND user_id = #{userId}

SELECT COUNT(*)
FROM user_learned_words
WHERE user_id = #{userId} AND type = #{type}

SELECT COUNT(*)
FROM user_favorites
WHERE user_id = #{userId} AND word_id = #{wordId}

SELECT *
FROM business_words
WHERE id = #{id}

